  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In a patient, brigatinib CSF-to-serum ratio was 0.012 with CSF 13.23 ng/mL versus plasma 1039 ng/mL, indicating poor CNS penetration after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In wild-type mice, peposertib Kp,uu,brain was 5% after oral administration, indicating severely restricted free brain distribution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Human PET measurements confirmed high brain uptake of [11C]AZ10419369, demonstrating meaningful CNS access in humans.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Fail: the preponderance of transferred direct in-vivo evidence—human CSF ratio 0.012, Kp,uu,brain 5%, negligible brain penetration, and efflux-restricted uptake—supports inadequate CNS access; one human PET-positive molecule is outweighed by multiple negative direct records.",
  "evidence_gaps": [
    "Molecule 4 is mixed: human and nonhuman primate PET show high uptake, but rodent baseline uptake is low and efflux-sensitive; this positive evidence represents a single chemotype against many negative records.",
    "Several negative records use CSF/plasma ratios or Kp,uu,brain, which may not capture total brain exposure, but the direct human CSF and PET data are consistent with poor access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

